using System;using System.IO;using System.Reflection;using System.Drawing;using System.Runtime.InteropServices;using System.Diagnostics;using System.Windows.Forms;
class InstallerLifecycleUiTests {
 static int count;static void Check(bool value,string name){if(!value)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}static T Get<T>(object o,string n){return (T)o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
 delegate bool WindowProc(IntPtr h,IntPtr p);[DllImport("user32.dll")]static extern bool EnumWindows(WindowProc proc,IntPtr l);[DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr h,out uint pid);[DllImport("user32.dll")]static extern bool PostMessage(IntPtr h,uint m,IntPtr w,IntPtr l);[DllImport("user32.dll",CharSet=CharSet.Unicode)]static extern int GetClassName(IntPtr h,System.Text.StringBuilder text,int max);
 [STAThread]static int Main(){try{Application.SetUnhandledExceptionMode(UnhandledExceptionMode.ThrowException);Application.EnableVisualStyles();var field=typeof(Setup).GetField("installed",BindingFlags.Static|BindingFlags.NonPublic);field.SetValue(null,null);using(var setup=(Form)Activator.CreateInstance(typeof(Setup),true)){setup.Show();Application.DoEvents();Check(Get<Button>(setup,"action").Text=="安装言渡","fresh install has only installation action");Check(Get<Button>(setup,"browse").Enabled&&!Get<TextBox>(setup,"location").ReadOnly,"fresh path is editable");bool opened=false;using(var timer=new Timer{Interval=100}){timer.Tick+=delegate{EnumWindows(delegate(IntPtr h,IntPtr l){uint pid;GetWindowThreadProcessId(h,out pid);var name=new System.Text.StringBuilder(100);GetClassName(h,name,100);if(pid==(uint)Process.GetCurrentProcess().Id&&name.ToString()=="#32770"){opened=true;PostMessage(h,0x10,IntPtr.Zero,IntPtr.Zero);}return true;},IntPtr.Zero);};timer.Start();Get<Button>(setup,"browse").PerformClick();timer.Stop();}Check(opened,"directory button opens a real folder selection dialog");using(var image=new Bitmap(setup.Width,setup.Height)){setup.DrawToBitmap(image,new Rectangle(Point.Empty,setup.Size));image.Save("personal/bin/v210-installer.png");}setup.Close();}
  using(var uninstall=new Uninstall()){uninstall.Show();Application.DoEvents();Check(!Get<CheckBox>(uninstall,"purge").Checked,"complete removal is an explicit unchecked option");Check(Get<CheckBox>(uninstall,"purge").Text.Contains("API 配置")&&Get<Button>(uninstall,"remove").Text=="卸载言渡","uninstaller describes private data choice");Get<CheckBox>(uninstall,"purge").Checked=true;Check(Get<CheckBox>(uninstall,"purge").Checked,"complete removal checkbox can be selected");using(var image=new Bitmap(uninstall.Width,uninstall.Height)){uninstall.DrawToBitmap(image,new Rectangle(Point.Empty,uninstall.Size));image.Save("personal/bin/v210-uninstaller.png");}uninstall.Close();}
  Console.WriteLine("OK "+count+" real installer dialog and uninstall UI checks; no installation or uninstall executed");return 0;
 }catch(Exception ex){Console.WriteLine("FAIL "+ex.Message);return 1;}}
}
